From e294776e909b7731d656720fdfb6bc7445c1caab Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:31:38 +0100
Subject: [PATCH] applet: load icons and notifyrc files bundled in the package

Widgets couldn't ship their own icon or notification events, so their
notifications were silently dropped. Add contents/icons as an icon
fallback path and contents/notifyrc as a source for the event config.

BUG: 485340
---
 .../plasma_applet_packagestructure.cpp        |  2 ++
 src/plasma/private/applet_p.cpp               | 19 +++++++++++++++++++
 src/plasma/private/applet_p.h                 |  2 ++
 3 files changed, 23 insertions(+)

diff --git a/src/plasma/packagestructure/plasma_applet_packagestructure.cpp b/src/plasma/packagestructure/plasma_applet_packagestructure.cpp
index d91a776ea..57cebb842 100644
--- a/src/plasma/packagestructure/plasma_applet_packagestructure.cpp
+++ b/src/plasma/packagestructure/plasma_applet_packagestructure.cpp
@@ -24,6 +24,8 @@ public:
         package->setDefaultPackageRoot(QStringLiteral(PLASMA_RELATIVE_DATA_INSTALL_DIR "/plasmoids/"));

         package->addFileDefinition("configmodel", QStringLiteral("config/config.qml"));
+        package->addDirectoryDefinition("icons", QStringLiteral("icons"));
+        package->addDirectoryDefinition("notifyrc", QStringLiteral("notifyrc"));
         package->addFileDefinition("mainconfigxml", QStringLiteral("config/main.xml"));
         package->setRequired("metadata", true);
         package->addFileDefinition("metadata", QStringLiteral("metadata.desktop"));
diff --git a/src/plasma/private/applet_p.cpp b/src/plasma/private/applet_p.cpp
index 37297d115..1a149f739 100644
--- a/src/plasma/private/applet_p.cpp
+++ b/src/plasma/private/applet_p.cpp
@@ -15,6 +15,7 @@
 #include <QFile>
 #include <QFileInfo>
 #include <QGuiApplication>
+#include <QIcon>
 #include <QJsonArray>
 #include <QMessageBox>
 #include <QStandardPaths>
@@ -103,6 +104,24 @@ void AppletPrivate::init(const QVariantList &args)
         configAction->setText(i18nc("%1 is the name of the applet", "Configure %1...", q->title().replace(QLatin1Char('&'), QStringLiteral("&&"))));
     }

+    if (package.isValid()) {
+        // Icons and notification events shipped inside the package
+        if (const QString iconsDir = package.filePath("icons"); !iconsDir.isEmpty() && !QIcon::fallbackSearchPaths().contains(iconsDir)) {
+            QIcon::setFallbackSearchPaths(QIcon::fallbackSearchPaths() << iconsDir);
+        }
+        if (const QString notifyRcDir = package.filePath("notifyrc"); !notifyRcDir.isEmpty()) {
+            const QFileInfoList notifyRcFiles = QDir(notifyRcDir).entryInfoList({QStringLiteral("*.notifyrc")}, QDir::Files);
+            for (const QFileInfo &file : notifyRcFiles) {
+                KSharedConfig::Ptr events =
+                    KSharedConfig::openConfig(QLatin1String("knotifications6/") + file.fileName(), KConfig::NoGlobals, QStandardPaths::GenericDataLocation);
+                if (!events->additionalConfigSources().contains(file.filePath())) {
+                    events->addConfigSources({file.filePath()});
+                }
+                notifyRcConfigs << events;
+            }
+        }
+    }
+
     if (!appletDescription.isValid()) {
 #ifndef NDEBUG
         // qCDebug(LOG_PLASMA) << "Check your constructor! "
diff --git a/src/plasma/private/applet_p.h b/src/plasma/private/applet_p.h
index e9f7af074..c2961ce27 100644
--- a/src/plasma/private/applet_p.h
+++ b/src/plasma/private/applet_p.h
@@ -16,6 +16,7 @@
 #include <KConfigPropertyMap>
 #include <KConfigSkeleton>
 #include <KNotification>
+#include <KSharedConfig>

 #include <KPackage/Package>
 #include <qaction.h>
@@ -83,6 +84,7 @@ public:

     // config and package stuff
     KPackage::Package package;
+    QList<KSharedConfig::Ptr> notifyRcConfigs;
     KConfigLoader *configLoader = nullptr;
     KConfigPropertyMap *configPropertyMap = nullptr;

-- 
