From 788708faf4612c6896ed64c05b723571963febf8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:31:43 +0100
Subject: [PATCH] shellprivate: show the icon bundled in a widget's package

When a widget's icon isn't in the icon theme, Add Widgets showed a
generic file icon. Fall back to the matching file in the package's
contents/icons folder, so the theme can still override it.

BUG: 485340
---
 components/shellprivate/plasmaappletitemmodel.cpp | 11 +++++++++++
 1 file changed, 11 insertions(+)

diff --git a/components/shellprivate/plasmaappletitemmodel.cpp b/components/shellprivate/plasmaappletitemmodel.cpp
index 9ac696f463..38abf2c26f 100644
--- a/components/shellprivate/plasmaappletitemmodel.cpp
+++ b/components/shellprivate/plasmaappletitemmodel.cpp
@@ -293,6 +293,17 @@ QVariant PlasmaAppletItem::data(int role) const
                     }
                 } else {
                     m_iconName = m_info.iconName();
+                    if (!QIcon::hasThemeIcon(m_iconName)) {
+                        KPackage::Package pkg = KPackage::PackageLoader::self()->loadPackage(QStringLiteral("Plasma/Applet"));
+                        pkg.setDefaultPackageRoot(QStringLiteral("plasma/plasmoids"));
+                        pkg.setPath(m_info.pluginId());
+                        if (const QString iconsDir = pkg.filePath("icons"); !iconsDir.isEmpty()) {
+                            const QFileInfoList bundledIcons = QDir(iconsDir).entryInfoList({m_iconName + QLatin1String(".*")}, QDir::Files);
+                            if (!bundledIcons.isEmpty()) {
+                                m_iconName = bundledIcons.constFirst().filePath();
+                            }
+                        }
+                    }
                 }
             }
         }
-- 
